async function handle(job) {
  const done = await db.markIfNew(job.idempotencyKey);  // 처음이면 true
  if (!done) return;                     // 이미 처리함 → 건너뜀(중복 방지)
  await sendEmail(job.payload);           // 실제 작업(부작용)
  // markIfNew: UNIQUE 제약으로 이 키를 이미 봤나를 원자적으로(data-model, pay-idem)
}
// 큐는 최소 한 번 → 같은 job 이 두 번 올 수 있음 → 멱등이 필수

await queue.add('email', payload, {
  attempts: 5,                              // 최대 5번 시도
  backoff: { type: 'exponential', delay: 1000 },  // 1s, 2s, 4s, 8s, 16s
});
// 5번 다 실패 → DLQ(failed 큐)로 이동 → 다른 작업은 계속 처리

// DLQ 운영:
//  - 쌓이면 경보(모니터링). "안 보면 없는 것과 같다"
//  - 원인 조사 후 고쳐서 재처리하는 절차를 문서로
